//! Ignore rules behavior scenarios.

use super::*;

#[test]
fn target_save_preserves_repository_tracking_exceptions() {
    let fixture = Fixture::new();
    let control = fixture.target.join(".agents/.gitignore");
    std::fs::write(
        &control,
        "# Generated by Skillator\nobsolete-rule\n\n# Exception list for repository tracking\n!skills/skillator/\n",
    )
    .unwrap();
    let session = TargetWorkflow::load(&fixture.target).unwrap();
    let prepared =
        TargetWorkflow::prepare_save(&fixture.paths, &session, session.config.clone()).unwrap();

    TargetWorkflow::commit_save(prepared, Authorization::AllGuarded).unwrap();

    assert_eq!(
        std::fs::read_to_string(control).unwrap(),
        format!("{AGENTS_CONTROL}!skills/skillator/\n")
    );
    assert!(!fixture.target.join(".gitignore").exists());
}

#[test]
fn ordinary_sync_prefixes_an_existing_parent_ignore_without_losing_rules() {
    let fixture = Fixture::new();
    let control = fixture.target.join(".agents/.gitignore");
    std::fs::write(&control, "# Existing repository rules\n*.local\n").unwrap();

    let report = SyncWorkflow::run(
        &fixture.paths,
        &fixture.target,
        SyncMode::Apply { force: false },
    )
    .unwrap();

    assert_eq!(report.status, ReportStatus::InSync, "{report:#?}");
    assert_eq!(
        std::fs::read_to_string(control).unwrap(),
        format!("{AGENTS_CONTROL}# Existing repository rules\n*.local\n")
    );
}

#[test]
fn sync_and_save_upgrade_legacy_ignore_files_and_keep_local_controls_ignored() {
    let legacy = "# Generated by skillator.\nskills/.skillator-*\nskills/release-checklist\n";
    for save in [false, true] {
        for existing in [None, Some(legacy)] {
            assert_legacy_ignore_upgrade(save, existing);
        }
    }
}

#[test]
fn target_save_adds_repository_skill_exceptions_without_enablements() {
    let fixture = Fixture::new();
    let repository_skill = fixture.target.join(".agents/skills/project-skill");
    std::fs::create_dir_all(&repository_skill).unwrap();
    std::fs::write(
        repository_skill.join("SKILL.md"),
        "---\nname: project-skill\ndescription: Project-owned instructions\n---\n",
    )
    .unwrap();
    let session = TargetWorkflow::load(&fixture.target).unwrap();
    let original_enablements = session.config.enablements().to_vec();
    let repository_skills = RepositorySkillExceptions::from([(
        "agents".to_owned(),
        BTreeSet::from(["project-skill".to_owned()]),
    )]);
    let prepared = TargetWorkflow::prepare_save_with_repository_skills(
        &fixture.paths,
        &session,
        session.config.clone(),
        repository_skills,
    )
    .unwrap();

    TargetWorkflow::commit_save(prepared, Authorization::SafeOnly).unwrap();

    let saved = TargetWorkflow::load(&fixture.target).unwrap();
    assert_eq!(saved.config.enablements(), original_enablements);
    assert!(
        std::fs::read_to_string(fixture.target.join(".agents/.gitignore"))
            .unwrap()
            .contains("!skills/project-skill/\n")
    );
    assert!(repository_skill.join("SKILL.md").is_file());
}

fn assert_legacy_ignore_upgrade(save: bool, existing: Option<&str>) {
    let fixture = Fixture::new();
    let control = fixture.target.join(".agents/.gitignore");
    if let Some(existing) = existing {
        std::fs::write(&control, existing).unwrap();
    }
    let mut previous = None;
    for _ in 0..2 {
        let report = apply_ignore_upgrade(&fixture, save);
        assert_eq!(
            report.status,
            ReportStatus::InSync,
            "save={save}: {report:#?}"
        );
        let content = std::fs::read_to_string(&control).unwrap();
        assert!(content.starts_with(AGENTS_CONTROL), "{content}");
        if let Some(existing) = existing {
            assert!(
                content.ends_with(existing),
                "Existing rules lost: {content}"
            );
        }
        if let Some(previous) = previous {
            assert_eq!(
                content, previous,
                "Repeated sync/save changed the ignore rules"
            );
        }
        previous = Some(content);
        let ignored = support::git_output(
            &fixture.target,
            &[
                "check-ignore",
                ".agents/.gitignore",
                ".agents/skillator.yaml",
            ],
        );
        assert_eq!(ignored, ".agents/.gitignore\n.agents/skillator.yaml\n");
        assert!(!fixture.target.join(".gitignore").exists());
    }
}

fn apply_ignore_upgrade(fixture: &Fixture, save: bool) -> skillator::app::CommandReport {
    if save {
        let session = TargetWorkflow::load(&fixture.target).unwrap();
        let prepared =
            TargetWorkflow::prepare_save(&fixture.paths, &session, session.config.clone()).unwrap();
        TargetWorkflow::commit_save(prepared, Authorization::SafeOnly).unwrap()
    } else {
        SyncWorkflow::run(
            &fixture.paths,
            &fixture.target,
            SyncMode::Apply { force: false },
        )
        .unwrap()
    }
}
